1	// Package contextcmd interprets the arguments of the :ctx command. It is pure:
2	// no I/O and no UI imports, so every decision is table-testable.
3	package contextcmd
4	
5	import (
6		"fmt"
7		"strings"
8	)
9	
10	// Snapshot is the state of the world Resolve decides against.
11	type Snapshot struct {
12		Names             []string
13		Current, Previous string
14		Ready             bool
15	}
16	
17	// Kind is what the caller must do with an Action.
18	type Kind int
19	
20	const (
21		// List opens the context list overlay.
22		List Kind = iota
23		// Switch loads the context named Name.
24		Switch
25		// Create creates the context named Name and switches to it.
26		Create
27		// Refuse does nothing but report Text.
28		Refuse
29		// KeepOpen leaves the command line open and reports Text.
30		KeepOpen
31	)
32	
33	// Level is the footer severity of an Action's Text.
34	type Level int
35	
36	const (
37		// Info is a neutral fact.
38		Info Level = iota
39		// Warn means the request cannot be honored as typed.
40		Warn
41		// Error means the request is invalid or failed.
42		Error
43	)
44	
45	// Action is the outcome of Resolve.
46	type Action struct {
47		Kind  Kind
48		Name  string
49		Level Level
50		Text  string
51	}
52	
53	const (
54		// WordNew and WordPrevious are the reserved words of the context command.
55		WordNew      = "new"
56		wordList     = "list"
57		WordPrevious = "-"
58	
59		textUsageNew = "Usage: :ctx new <name>"
60		textUsage    = "Usage: :ctx <name>"
61		textNoPrev   = "No previous context in this session"
62		textNotReady = "Contexts are still loading — try again"
63	)
64	
65	// Footer texts the router needs outside Resolve, for a failure that surfaces
66	// after the decision (a race with the disk, a bad name reaching the loader).
67	
68	// AlreadyText is the footer text of a switch to the current context.
69	func AlreadyText(name string) string { return textAlready(name) }
70	
71	// InvalidText is the footer text of a name that fails the format.
72	func InvalidText(name string) string { return textInvalid(name) }
73	
74	// ReservedText is the footer text of a reserved word used as a name.
75	func ReservedText(name string) string { return textReserved(name) }
76	
77	// ExistsText is the footer text of a creation over an existing context.
78	func ExistsText(name string) string { return textExists(name) }
79	
80	// NotFoundText is the footer text of a missing context, without suggestion.
81	func NotFoundText(name string) string { return textNotFound(name, nil) }
82	
83	func textAlready(name string) string { return fmt.Sprintf("Already on context %q", name) }
84	
85	func textInvalid(name string) string {
86		return fmt.Sprintf("Invalid context name %q — use lowercase letters, digits and hyphens", name)
87	}
88	
89	func textReserved(name string) string {
90		return fmt.Sprintf("%q is reserved — choose another name", name)
91	}
92	
93	func textExists(name string) string {
94		return fmt.Sprintf("Context %q already exists — use :ctx %s to switch", name, name)
95	}
96	
97	// maxListedMatches caps how many ambiguous matches the footer names.
98	const maxListedMatches = 10
99	
100	func textAmbiguous(prefix string, matches []string) string {
101		list := strings.Join(matches, ", ")
102		if len(matches) > maxListedMatches {
103			list = strings.Join(matches[:maxListedMatches], ", ") +
104				fmt.Sprintf(", and %d more", len(matches)-maxListedMatches)
105		}
106		return fmt.Sprintf("%q matches %s — type more letters or press tab", prefix, list)
107	}
108	
109	func textPreviousGone(name string) string {
110		return fmt.Sprintf("Previous context %q no longer exists", name)
111	}
112	
113	func textNotFound(name string, names []string) string {
114		if near, ok := DidYouMean(name, names); ok {
115			return fmt.Sprintf("Context %q not found — did you mean %q? Use :ctx new %s to create it", name, near, name)
116		}
117		return fmt.Sprintf("Context %q not found — use :ctx new %s to create it", name, name)
118	}
119	
120	func refuse(level Level, text string) Action { return Action{Kind: Refuse, Level: level, Text: text} }
121	
122	func keepOpen(level Level, text string) Action {
123		return Action{Kind: KeepOpen, Level: level, Text: text}
124	}
125	
126	// ValidName reports whether name is made of lowercase letters, digits and
127	// hyphens only, mirroring config.ValidateContextName without importing it.
128	// It is the single source of that rule on the UI side.
129	func ValidName(name string) bool {
130		if name == "" {
131			return false
132		}
133		for _, r := range name {
134			if (r < 'a' || r > 'z') && (r < '0' || r > '9') && r != '-' {
135				return false
136			}
137		}
138		return true
139	}
140	
141	// cleanNames drops empty names and duplicates, keeping the first occurrence.
142	func cleanNames(names []string) []string {
143		out := make([]string, 0, len(names))
144		for _, n := range names {
145			if n != "" && !contains(out, n) {
146				out = append(out, n)
147			}
148		}
149		return out
150	}
151	
152	func contains(names []string, name string) bool {
153		for _, n := range names {
154			if n == name {
155				return true
156			}
157		}
158		return false
159	}
160	
161	// switchTo switches to name, or reports that it is already the current one.
162	func switchTo(name string, s Snapshot) Action {
163		if name == s.Current {
164			return refuse(Info, textAlready(name))
165		}
166		return Action{Kind: Switch, Name: name}
167	}
168	
169	// Resolve interprets the words after :ctx. highlighted is the suggestion the
170	// user chose with tab, or "" when none was chosen.
171	func Resolve(args []string, highlighted string, s Snapshot) Action {
172		s.Names = cleanNames(s.Names)
173		if len(args) == 0 || (len(args) == 1 && args[0] == wordList) {
174			return Action{Kind: List}
175		}
176		if !s.Ready {
177			return keepOpen(Warn, textNotReady)
178		}
179		if args[0] == WordNew {
180			return resolveNew(args[1:], s)
181		}
182		if len(args) > 1 {
183			return keepOpen(Warn, textUsage)
184		}
185		return resolveName(args[0], highlighted, s)
186	}
187	
188	// resolveNew handles ":ctx new <name>".
189	func resolveNew(rest []string, s Snapshot) Action {
190		if len(rest) != 1 {
191			return keepOpen(Warn, textUsageNew)
192		}
193		name := rest[0]
194		switch {
195		case name == WordNew || name == wordList || name == WordPrevious:
196			return refuse(Error, textReserved(name))
197		case !ValidName(name):
198			return refuse(Error, textInvalid(name))
199		case contains(s.Names, name):
200			return refuse(Warn, textExists(name))
201		}
202		return Action{Kind: Create, Name: name}
203	}
204	
205	// resolveName handles ":ctx <arg>": previous, exact, prefix, or unknown.
206	func resolveName(arg, highlighted string, s Snapshot) Action {
207		if arg == WordPrevious {
208			if s.Previous == "" {
209				return refuse(Warn, textNoPrev)
210			}
211			if !contains(s.Names, s.Previous) {
212				return refuse(Error, textPreviousGone(s.Previous))
213			}
214			return switchTo(s.Previous, s)
215		}
216		if !ValidName(arg) {
217			return refuse(Error, textInvalid(arg))
218		}
219		if contains(s.Names, arg) {
220			return switchTo(arg, s)
221		}
222		matches := Match(arg, s.Names)
223		switch {
224		case len(matches) == 0:
225			return refuse(Error, textNotFound(arg, s.Names))
226		case len(matches) == 1:
227			return switchTo(matches[0], s)
228		case contains(matches, highlighted):
229			return switchTo(highlighted, s)
230		}
231		return keepOpen(Warn, textAmbiguous(arg, matches))
232	}
233	
234	// Match returns the names starting with prefix (case-insensitive), an exact
235	// match first, the others in their original order.
236	func Match(prefix string, names []string) []string {
237		p := strings.ToLower(prefix)
238		out := []string{}
239		for _, n := range names {
240			if strings.ToLower(n) == p {
241				out = append(out, n)
242			}
243		}
244		for _, n := range names {
245			l := strings.ToLower(n)
246			if l != p && strings.HasPrefix(l, p) {
247				out = append(out, n)
248			}
249		}
250		return out
251	}
252	
253	// DidYouMean returns the closest name: edit distance <= min(2, half the
254	// shorter length), or a common start of at least 3 characters. Ties go to the
255	// first name; empty names are never offered.
256	func DidYouMean(name string, names []string) (string, bool) {
257		best, bestDist := "", 0
258		for _, n := range names {
259			if n == "" {
260				continue
261			}
262			d := editDistance(name, n)
263			if d > maxDistance(name, n) && commonPrefixLen(name, n) < 3 {
264				continue
265			}
266			if best == "" || d < bestDist {
267				best, bestDist = n, d
268			}
269		}
270		return best, best != ""
271	}
272	
273	// maxDistance is the largest edit distance still considered a typo.
274	func maxDistance(a, b string) int {
275		return min(2, min(len([]rune(a)), len([]rune(b)))/2)
276	}
277	
278	func commonPrefixLen(a, b string) int {
279		ra, rb := []rune(a), []rune(b)
280		n := 0
281		for n < len(ra) && n < len(rb) && ra[n] == rb[n] {
282			n++
283		}
284		return n
285	}
286	
287	// editDistance is the Levenshtein distance between a and b.
288	func editDistance(a, b string) int {
289		ra, rb := []rune(a), []rune(b)
290		prev := make([]int, len(rb)+1)
291		for j := range prev {
292			prev[j] = j
293		}
294		for i := 1; i <= len(ra); i++ {
295			cur := make([]int, len(rb)+1)
296			cur[0] = i
297			for j := 1; j <= len(rb); j++ {
298				cost := 1
299				if ra[i-1] == rb[j-1] {
300					cost = 0
301				}
302				cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
303			}
304			prev = cur
305		}
306		return prev[len(rb)]
307	}
